import React, { useState, useEffect } from 'react';
import api from '../services/api';
import EventCard from '../components/EventCard';
import LoadingSpinner from '../components/LoadingSpinner';

const Events = () => {
    const [events, setEvents] = useState([]);
    const [loading, setLoading] = useState(true);
    const [filters, setFilters] = useState({
        search: '',
        category: 'all',
        location: 'all',
        date: 'all'
    });
    const [categories, setCategories] = useState([]);
    const [locations, setLocations] = useState([]);
    const [pagination, setPagination] = useState({
        currentPage: 1,
        totalPages: 1,
        totalEvents: 0
    });

    useEffect(() => {
        fetchCategories();
        fetchEvents();
    }, []);

    useEffect(() => {
        fetchEvents();
    }, [filters, pagination.currentPage]);

    const fetchCategories = async () => {
        try {
            const response = await api.get('/events/categories/all');
            setCategories(['all', ...response.data]);
        } catch (error) {
            console.error('Error fetching categories:', error);
        }
    };

    const fetchEvents = async () => {
        setLoading(true);
        try {
            const params = new URLSearchParams({
                page: pagination.currentPage,
                limit: 9,
                ...(filters.search && { search: filters.search }),
                ...(filters.category !== 'all' && { category: filters.category }),
                ...(filters.location !== 'all' && { location: filters.location }),
                ...(filters.date !== 'all' && { date: filters.date })
            });

            const response = await api.get(`/events?${params}`);
            setEvents(response.data.events);
            setPagination({
                currentPage: response.data.currentPage,
                totalPages: response.data.totalPages,
                totalEvents: response.data.totalEvents
            });

            const uniqueLocations = [...new Set(response.data.events.map(e => e.location))];
            setLocations(['all', ...uniqueLocations]);
        } catch (error) {
            console.error('Error fetching events:', error);
        } finally {
            setLoading(false);
        }
    };

    const handleFilterChange = (e) => {
        const { name, value } = e.target;
        setFilters(prev => ({ ...prev, [name]: value }));
        setPagination(prev => ({ ...prev, currentPage: 1 }));
    };

    const handleSearch = (e) => {
        e.preventDefault();
        fetchEvents();
    };

    const handlePageChange = (newPage) => {
        setPagination(prev => ({ ...prev, currentPage: newPage }));
        window.scrollTo({ top: 0, behavior: 'smooth' });
    };

    return (
        <div className="min-h-screen bg-gray-50 py-8">
            <div className="container mx-auto px-4">
                <h1 className="text-3xl font-bold mb-8 text-gray-800">
                    Browse Events
                </h1>

                {/* Filters */}
                <div className="bg-white rounded-lg shadow p-6 mb-8">
                    <form onSubmit={handleSearch} className="space-y-4">
                        <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
                            <input
                                type="text"
                                name="search"
                                placeholder="Search events..."
                                value={filters.search}
                                onChange={handleFilterChange}
                                className="border rounded-lg px-4 py-2 focus:outline-none focus:ring-2 focus:ring-purple-600"
                            />
                            
                            <select
                                name="category"
                                value={filters.category}
                                onChange={handleFilterChange}
                                className="border rounded-lg px-4 py-2 focus:outline-none focus:ring-2 focus:ring-purple-600"
                            >
                                {categories.map(cat => (
                                    <option key={cat} value={cat}>
                                        {cat === 'all' ? 'All Categories' : cat}
                                    </option>
                                ))}
                            </select>

                            <select
                                name="location"
                                value={filters.location}
                                onChange={handleFilterChange}
                                className="border rounded-lg px-4 py-2 focus:outline-none focus:ring-2 focus:ring-purple-600"
                            >
                                {locations.map(loc => (
                                    <option key={loc} value={loc}>
                                        {loc === 'all' ? 'All Locations' : loc}
                                    </option>
                                ))}
                            </select>

                            <select
                                name="date"
                                value={filters.date}
                                onChange={handleFilterChange}
                                className="border rounded-lg px-4 py-2 focus:outline-none focus:ring-2 focus:ring-purple-600"
                            >
                                <option value="all">All Dates</option>
                                <option value="today">Today</option>
                                <option value="tomorrow">Tomorrow</option>
                                <option value="this-week">This Week</option>
                                <option value="this-month">This Month</option>
                            </select>
                        </div>
                        
                        <button
                            type="submit"
                            className="bg-purple-600 text-white px-6 py-2 rounded-lg hover:bg-purple-700 transition"
                        >
                            Apply Filters
                        </button>
                    </form>
                </div>

                {/* Results */}
                {loading ? (
                    <LoadingSpinner />
                ) : (
                    <>
                        <p className="text-gray-600 mb-4">
                            Found {pagination.totalEvents} events
                        </p>

                        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
                            {events.map(event => (
                                <EventCard key={event._id} event={event} />
                            ))}
                        </div>

                        {/* Pagination */}
                        {pagination.totalPages > 1 && (
                            <div className="flex justify-center mt-8 space-x-2">
                                <button
                                    onClick={() => handlePageChange(pagination.currentPage - 1)}
                                    disabled={pagination.currentPage === 1}
                                    className="px-4 py-2 border rounded-lg disabled:opacity-50 disabled:cursor-not-allowed hover:bg-gray-100"
                                >
                                    Previous
                                </button>
                                
                                {[...Array(pagination.totalPages)].map((_, i) => (
                                    <button
                                        key={i + 1}
                                        onClick={() => handlePageChange(i + 1)}
                                        className={`px-4 py-2 border rounded-lg ${
                                            pagination.currentPage === i + 1
                                                ? 'bg-purple-600 text-white'
                                                : 'hover:bg-gray-100'
                                        }`}
                                    >
                                        {i + 1}
                                    </button>
                                ))}

                                <button
                                    onClick={() => handlePageChange(pagination.currentPage + 1)}
                                    disabled={pagination.currentPage === pagination.totalPages}
                                    className="px-4 py-2 border rounded-lg disabled:opacity-50 disabled:cursor-not-allowed hover:bg-gray-100"
                                >
                                    Next
                                </button>
                            </div>
                        )}
                    </>
                )}
            </div>
        </div>
    );
};

export default Events;
